  sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::IssueBirth);for _ in 0..16{if actor.inspect(|p|p.lease.is_some()){break}sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Issue);}assert_eq!(actor.inspect(|p|p.lease.as_ref().unwrap().get()as*const String as usize),address);assert!(actor.inspect(|p|p.lease.as_ref().unwrap().get().as_str()==expected));assert_eq!(serde_json::from_str::<String>(&serde_json::to_string(expected).unwrap()).unwrap(),expected);
